INSERT INTO Language_en_US(Tag,Text) VALUES
 ('TXT_KEY_CWC3_SCARECROW_CIV','Assembly of Scarecrows'),
 ('TXT_KEY_CWC3_SCARECROW_SHORT','Assembly of Scarecrows'),
 ('TXT_KEY_CWC3_SCARECROW_ADJECTIVE','Scarecrow'),
 ('TXT_KEY_CWC3_SCARECROW_LEADER','Old Man Thistle'),
 ('TXT_KEY_CWC3_SCARECROW_TRAIT','The Fields Have Eyes'),
 ('TXT_KEY_CWC3_SCARECROW_TRAIT_HELP','Owned cities with at least 3 owned, unpillaged Farms within 3 tiles gain +2 Culture and +1 Production. At 6 Farms they also gain +2 Food. Farms need not be worked; overlapping cities count independently.'),
 ('TXT_KEY_CWC3_SCARECROW_CIV_PEDIA','Living scarecrows gather beneath the harvest bells, keeping watch over the fields that sustain their assembly. Old Man Thistle speaks for the patient guardians of each furrow.'),
 ('TXT_KEY_CWC3_SCARECROW_STRATEGY','Plan clusters of three, six and nine Farms. Overlapping city radii share agricultural investment. Repair pillaged fields quickly, defend them with Sentinels, and use Food to support cultural specialists.'),
 ('TXT_KEY_CWC3_SCARECROW_LEADER_PEDIA','Living scarecrows gather beneath the harvest bells, keeping watch over the fields that sustain their assembly. Old Man Thistle speaks for the patient guardians of each furrow.'),
 ('TXT_KEY_CWC3_SCARECROW_DAWN','Old Man Thistle, guide Assembly of Scarecrows. Plan clusters of three, six and nine Farms. Overlapping city radii share agricultural investment. Repair pillaged fields quickly, defend them with Sentinels, and use Food to support cultural specialists.'),
 ('TXT_KEY_CWC3_SCARECROW_UNIT','Wicker Sentinel'),
 ('TXT_KEY_CWC3_SCARECROW_UNIT_HELP','Replaces the active CP Spearman. +1 Sight and +15% Combat Strength in native friendly territory, including qualifying Open Borders. Native melee combat uses the battle tile. Promotion persists through upgrades.'),
 ('TXT_KEY_CWC3_SCARECROW_UNIT_PEDIA','Living scarecrows gather beneath the harvest bells, keeping watch over the fields that sustain their assembly. Old Man Thistle speaks for the patient guardians of each furrow. +1 Sight and +15% Combat Strength in native friendly territory, including qualifying Open Borders. Native melee combat uses the battle tile. Promotion persists through upgrades.'),
 ('TXT_KEY_CWC3_SCARECROW_UNIT_STRATEGY','+1 Sight and +15% Combat Strength in native friendly territory, including qualifying Open Borders. Native melee combat uses the battle tile. Promotion persists through upgrades. Preserves all other active CP unit properties and companions.'),
 ('TXT_KEY_CWC3_SCARECROW_BUILDING','Harvest Bell'),
 ('TXT_KEY_CWC3_SCARECROW_BUILDING_HELP','Replaces the active CP Granary. +1 permanent Culture, plus +1 Gold per 3 qualifying owned, unpillaged Farms within 3 tiles (maximum +3 Gold). Retains all active Granary effects.'),
 ('TXT_KEY_CWC3_SCARECROW_BUILDING_PEDIA','Living scarecrows gather beneath the harvest bells, keeping watch over the fields that sustain their assembly. Old Man Thistle speaks for the patient guardians of each furrow. +1 permanent Culture, plus +1 Gold per 3 qualifying owned, unpillaged Farms within 3 tiles (maximum +3 Gold). Retains all active Granary effects.'),
 ('TXT_KEY_CWC3_SCARECROW_BUILDING_STRATEGY','Plan clusters of three, six and nine Farms. Overlapping city radii share agricultural investment. Repair pillaged fields quickly, defend them with Sentinels, and use Food to support cultural specialists.'),
